import fs from'node:fs';import path from'node:path';import assert from'node:assert/strict';import{createHash}from'node:crypto';import{gunzipSync}from'node:zlib';import{buildPreparedPolygonMeshes}from'../../tools/build-prepared-polygon-mesh.mjs';import{readBuiltinCountryStoredBytes}from'../../tools/builtin-country-bytes.mjs';import{sharedSourceManifest}from'../../tools/package-shared-core-assets.mjs';
const b='build-native/territorial-recipe/',root=path.resolve(b,'historical-detail-darja-bundle'),plan=JSON.parse(fs.readFileSync(path.join(root,'staging-plan.json'))),read=f=>JSON.parse(fs.readFileSync(path.join(root,f))),sha=v=>createHash('sha256').update(v).digest('hex'),manifestFile='assets/data/prepared-polygons/generated/v2/manifest.json',original=read(manifestFile),oldCandidate=JSON.parse(fs.readFileSync(b+manifestFile)),index=read('assets/data/builtin-world/generated/v1/index.json'),si=read('assets/data/territorial-entities/generated/v2/index.json'),wanted=new Set();
function collect(v){if(!v||typeof v!=='object')return;if(['Polygon','MultiPolygon'].includes(v.type)&&Array.isArray(v.coordinates)){wanted.add(sha(JSON.stringify([v.type,v.coordinates])));return;}Object.values(v).forEach(collect);}
for(const id of plan.preparationInputCountries){const e=index.entities.find(r=>r.entityId===id);collect(JSON.parse(gunzipSync(readBuiltinCountryStoredBytes(e,f=>fs.readFileSync(path.join(root,'assets/data/builtin-world/generated/v1',f))))));for(const sid of index.sourceIdentities.find(r=>r.projectEntityId===id).sourceEntityIds){const s=si.entities.find(r=>r.entityId===sid);collect(JSON.parse(gunzipSync(fs.readFileSync(path.join(root,'assets/data/territorial-entities/generated/v2',s.file)))));}}
let seedCount=0,reusedInputFiles=0,inputBytes=0;for(const digest of wanted){const spec=original.meshes[digest]||oldCandidate.meshes[digest];if(!spec)continue;const candidates=[path.resolve(b,spec.url),path.resolve(spec.url)],src=candidates.find(f=>fs.existsSync(f));if(!src)continue;const bytes=fs.readFileSync(src);assert.equal(bytes.length,spec.compressedBytes);assert.equal(sha(bytes),spec.sha256);const dest=path.join(root,spec.url);if(!fs.existsSync(dest)){fs.mkdirSync(path.dirname(dest),{recursive:true});fs.writeFileSync(dest,bytes,{flag:'wx'});reusedInputFiles++;inputBytes+=bytes.length;}if(!original.meshes[digest]){original.meshes[digest]=spec;seedCount++;}}
fs.writeFileSync(path.join(root,manifestFile),JSON.stringify(original,null,2)+'\n');console.log({selectedMeshInputsCopied:reusedInputFiles,inputBytes,priorCandidateMeshEntriesReused:seedCount});
const writes=[],write=(file,bytes)=>{const rel=path.relative(root,file);assert.ok(!rel.startsWith('..')&&!path.isAbsolute(rel));fs.mkdirSync(path.dirname(file),{recursive:true});fs.writeFileSync(file,bytes);writes.push({file:rel.replaceAll('\\','/'),bytes:Buffer.byteLength(bytes),sha256:sha(bytes)});};
const country=buildPreparedPolygonMeshes({root,countryIds:plan.preparationInputCountries,countryMonths:plan.countryMonths,sourceIdentity:()=>sharedSourceManifest(process.cwd()),write});
console.log({phase:'country',selected:country.count,reused:country.reused});const physical=[];for(const month of plan.physicalMonths){const r=buildPreparedPolygonMeshes({root,physicalMonth:month,sourceIdentity:()=>sharedSourceManifest(process.cwd()),write});physical.push({month,count:r.count,reused:r.reused,digests:r.selectedDigests,storedBytes:r.bytes});console.log({phase:'physical',month,count:r.count,reused:r.reused});}
const final=read(manifestFile),activeOriginal=JSON.parse(fs.readFileSync(manifestFile));let preserved=0;for(const[d,spec]of Object.entries(activeOriginal.meshes)){assert.deepEqual(final.meshes[d],spec);preserved++;}
for(const v of plan.versions)if(v.compiledDigest){assert.ok(final.meshes[v.nativeDigest]);assert.ok(final.meshes[v.compiledDigest]);}
assert.deepEqual(physical[0].digests,physical[1].digests,'Same selected water/land context must reuse physical meshes across the two checked months');
const result={scope:plan.preparationInputCountries,countryMonths:plan.countryMonths,country:{count:country.count,reused:country.reused,digests:country.selectedDigests,storedBytes:country.bytes},physical,originalActiveManifestEntriesPreserved:preserved,priorCandidateMeshEntriesReused:seedCount,meshInputCopies:reusedInputFiles,meshInputBytes:inputBytes,finalManifestEntryCount:Object.keys(final.meshes).length,writes};
fs.writeFileSync(path.join(root,'prepared-result.json'),JSON.stringify(result,null,2)+'\n',{flag:'wx'});console.log({completed:true,originalActiveEntriesPreserved:preserved,newArtifactWrites:writes.length});
